using Wip.Bones.Domain;
using Wip.Bones.Engine;
using System.Collections.Generic;
using System.Linq;

public sealed class SeatStrategy : IBonesPlayerSlot
{
    public BonesMove ChooseMove(BonesRoundState state, IReadOnlyList<BonesMove> legalMoves)
    {
        if (legalMoves.Count == 0)
            throw new System.InvalidOperationException("No legal moves.");

        var nonPassMoves = legalMoves.Where(m => !m.IsPass).ToList();
        if (nonPassMoves.Count == 0)
            return legalMoves[0];

        var board = state.Board;
        var hand = state.Hands.GetHand(state.CurrentPlayer);
        int leftEndPip = board.LeftEnd?.Pip.Value ?? -1;
        int rightEndPip = board.RightEnd?.Pip.Value ?? -1;

        // Count pip frequencies in hand
        int[] pipCounts = new int[7];
        foreach (var t in hand.Tiles)
        {
            pipCounts[t.LowPip.Value]++;
            if (!t.IsDouble)
                pipCounts[t.HighPip.Value]++;
        }

        // Count total pips in hand for endgame awareness
        int handTotalPips = 0;
        foreach (var t in hand.Tiles)
            handTotalPips += t.TotalPips;

        int handTileCount = hand.Tiles.Length;
        bool isEndgame = handTileCount <= 3;

        // Count global pip frequencies from board tiles
        int[] globalPipCounts = new int[7];
        foreach (var chainTile in board.Tiles)
        {
            globalPipCounts[chainTile.Tile.LowPip.Value]++;
            if (!chainTile.Tile.IsDouble)
                globalPipCounts[chainTile.Tile.HighPip.Value]++;
        }

        // Estimate opponent pip counts (28 total per pip minus our hand minus board)
        int[] opponentPipCounts = new int[7];
        for (int i = 0; i < 7; i++)
        {
            opponentPipCounts[i] = 28 - globalPipCounts[i] - pipCounts[i];
            if (opponentPipCounts[i] < 0) opponentPipCounts[i] = 0;
        }

        BonesMove? bestMove = null;
        int bestScore = int.MinValue;

        foreach (var move in nonPassMoves)
        {
            var tile = move.Tile!.Value;
            int score = 0;

            // Strong bonus for doubles: they provide blocking power and flexibility
            if (tile.IsDouble)
                score += 60;

            // Prefer playing high-pip tiles to reduce hand total
            score += tile.TotalPips * 3;

            bool matchesLeft = leftEndPip >= 0 && (tile.LowPip.Value == leftEndPip || tile.HighPip.Value == leftEndPip);
            bool matchesRight = rightEndPip >= 0 && (tile.LowPip.Value == rightEndPip || tile.HighPip.Value == rightEndPip);

            if (matchesLeft || matchesRight)
                score += 80;
            else
                score -= 50;

            // Heavily penalize plays that leave us with no matching ends
            if (leftEndPip >= 0 || rightEndPip >= 0)
            {
                int remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatching == 0 && !tile.IsDouble)
                    score -= 150;
            }

            // Prefer playing on the side that matches our stronger pip holdings
            if (matchesLeft)
            {
                int leftPipCount = pipCounts[leftEndPip];
                score += leftPipCount * 8;
                if (move.Side == BonesBoardSide.Left)
                    score += 15;
            }
            if (matchesRight)
            {
                int rightPipCount = pipCounts[rightEndPip];
                score += rightPipCount * 8;
                if (move.Side == BonesBoardSide.Right)
                    score += 15;
            }

            // Bonus for playing a tile that matches pips we have many of (future options)
            int lowPipCount = pipCounts[tile.LowPip.Value];
            int highPipCount = tile.IsDouble ? 0 : pipCounts[tile.HighPip.Value];
            score += (lowPipCount + highPipCount) * 5;

            // Penalty for playing a double when we have many of that pip (risk of being stuck)
            if (tile.IsDouble)
            {
                int otherPip = tile.LowPip.Value;
                if (pipCounts[otherPip] >= 3)
                    score -= 35;
            }

            // Prefer playing on the side with fewer chain tiles to maintain balance
            if (matchesLeft && matchesRight)
            {
                int leftChainCount = 0, rightChainCount = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainLeftPip.Value == leftEndPip)
                        leftChainCount++;
                    if (chainTile.ChainRightPip.Value == rightEndPip)
                        rightChainCount++;
                }
                if (leftChainCount < rightChainCount && move.Side == BonesBoardSide.Left)
                    score += 20;
                else if (rightChainCount < leftChainCount && move.Side == BonesBoardSide.Right)
                    score += 20;
            }

            // Avoid playing a tile that would create a very unbalanced board
            if (leftEndPip >= 0 && rightEndPip >= 0)
            {
                int leftHandPips = 0, rightHandPips = 0;
                foreach (var t in hand.Tiles)
                {
                    if (t.LowPip.Value == leftEndPip || t.HighPip.Value == leftEndPip)
                        leftHandPips += t.TotalPips;
                    if (t.LowPip.Value == rightEndPip || t.HighPip.Value == rightEndPip)
                        rightHandPips += t.TotalPips;
                }
                if (leftHandPips > rightHandPips * 2 && move.Side == BonesBoardSide.Left)
                    score -= 25;
                if (rightHandPips > leftHandPips * 2 && move.Side == BonesBoardSide.Right)
                    score -= 25;
            }

            // Endgame: prefer playing doubles when hand is small to reduce opponent options
            if (isEndgame && tile.IsDouble)
                score += 40;

            // Prefer playing tiles that reduce our pip count variance (shed large tiles)
            if (handTileCount > 1)
            {
                int avgPip = handTotalPips / handTileCount;
                if (tile.TotalPips >= avgPip * 1.5)
                    score += 15;
            }

            // Revised opponent modeling: estimate opponent's weak pips by tracking played pips
            int lowPipOpponent = opponentPipCounts[tile.LowPip.Value];
            int highPipOpponent = tile.IsDouble ? 0 : opponentPipCounts[tile.HighPip.Value];
            score -= (lowPipOpponent + highPipOpponent) * 2;

            // Revised: Prefer playing on the side where opponent has fewer matching tiles
            if (matchesLeft)
            {
                int opponentLeftCount = opponentPipCounts[leftEndPip];
                if (opponentLeftCount <= 2)
                    score += 25;
                else if (opponentLeftCount >= 5)
                    score -= 15;
            }
            if (matchesRight)
            {
                int opponentRightCount = opponentPipCounts[rightEndPip];
                if (opponentRightCount <= 2)
                    score += 25;
                else if (opponentRightCount >= 5)
                    score -= 15;
            }

            // Prefer playing on the side that has a higher pip value (to increase opponent's hand liability)
            if (matchesLeft && leftEndPip >= 0)
                score += leftEndPip * 2;
            if (matchesRight && rightEndPip >= 0)
                score += rightEndPip * 2;

            // Penalize playing a double when opponent is likely to have that pip (to avoid giving them options)
            if (tile.IsDouble)
            {
                int doublePip = tile.LowPip.Value;
                if (opponentPipCounts[doublePip] >= 4)
                    score -= 25;
            }

            // In non-endgame, prefer playing tiles that match both ends to maintain options
            if (!isEndgame && matchesLeft && matchesRight)
                score += 30;

            // Avoid playing a tile that would create a long chain on one side (risk of being blocked)
            if (matchesLeft && matchesRight)
            {
                int totalChain = board.Tiles.Length;
                if (totalChain > 20 && move.Side == BonesBoardSide.Left)
                    score -= 10;
                if (totalChain > 20 && move.Side == BonesBoardSide.Right)
                    score -= 10;
            }

            // NEW: Strongly penalize playing a tile that would leave us with exactly one matching end and that end is a high pip
            // This prevents being forced into bad positions
            if (matchesLeft != matchesRight && (leftEndPip >= 0 || rightEndPip >= 0))
            {
                int remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatching == 1)
                {
                    int remainingEndPip = matchesLeft ? leftEndPip : rightEndPip;
                    if (remainingEndPip >= 5)
                        score -= 40;
                }
            }

            // NEW: Prefer playing tiles that create a new end pip that we have many of
            int newLeftPip = -1, newRightPip = -1;
            if (matchesLeft)
            {
                newLeftPip = tile.LowPip.Value == leftEndPip ? tile.HighPip.Value : tile.LowPip.Value;
                if (pipCounts[newLeftPip] >= 2)
                    score += 15;
            }
            if (matchesRight)
            {
                newRightPip = tile.LowPip.Value == rightEndPip ? tile.HighPip.Value : tile.LowPip.Value;
                if (pipCounts[newRightPip] >= 2)
                    score += 15;
            }

            // NEW: Avoid playing a tile that would create an end pip the opponent has many of
            if (newLeftPip >= 0 && opponentPipCounts[newLeftPip] >= 4)
                score -= 20;
            if (newRightPip >= 0 && opponentPipCounts[newRightPip] >= 4)
                score -= 20;

            // NEW: In early game, prefer playing on the side with lower pip to keep options open
            if (!isEndgame && handTileCount > 5)
            {
                if (matchesLeft && leftEndPip <= 2)
                    score += 10;
                if (matchesRight && rightEndPip <= 2)
                    score += 10;
            }

            // NEW: Prefer playing doubles when opponent has few of that pip (to block them)
            if (tile.IsDouble && opponentPipCounts[tile.LowPip.Value] <= 2)
                score += 30;

            // NEW: In endgame, heavily penalize playing a tile that would leave us with no matching ends
            if (isEndgame && (leftEndPip >= 0 || rightEndPip >= 0))
            {
                int remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatching == 0)
                    score -= 300;
            }

            if (score > bestScore)
            {
                bestScore = score;
                bestMove = move;
            }
        }

        if (bestMove == null)
            bestMove = nonPassMoves[0];

        return bestMove;
    }

    private int CountMatchingAfterPlay(BonesHand hand, BonesTile playedTile, int leftEndPip, int rightEndPip)
    {
        int count = 0;
        foreach (var tile in hand.Tiles)
        {
            if (tile.LowPip.Value == playedTile.LowPip.Value && tile.HighPip.Value == playedTile.HighPip.Value && tile.TotalPips == playedTile.TotalPips)
                continue;

            if (leftEndPip >= 0 && (tile.LowPip.Value == leftEndPip || tile.HighPip.Value == leftEndPip))
                count++;
            if (rightEndPip >= 0 && (tile.LowPip.Value == rightEndPip || tile.HighPip.Value == rightEndPip))
                count++;
        }
        return count;
    }
}
